  WhiteSpace,
  Comment,

  // External code pragma
  ExternalPragma,

  // Multi-character operators (before single-character)
  DoubleDot,
  Power,
  RefAssign,
  Assign,
  OutputAssign,
  NotEqual,
  LessEqual,
  GreaterEqual,

  // Typed and time/date literals (before keywords — BYTE#255, TOD#12:00 must not split)
  TimeLiteral,
  DateTimeLiteral,
  DateLiteral,
  TimeOfDayLiteral,
  TypedLiteral,

  // Keywords (before Identifier)
  END_PROGRAM,
  END_FUNCTION_BLOCK,
  END_FUNCTION,
  END_CONFIGURATION,
  END_RESOURCE,
  END_STRUCT,
  END_TYPE,
